<script setup lang="ts">import {computed} from 'vue';import {fixed} from '../utils/format';const props=defineProps<{result:any}>();const bounds=computed(()=>{const rows=props.result.robustness.samples,x=rows.map((r:any)=>r.strength),y=rows.map((r:any)=>r.cost);x.push(props.result.spec.strength_min);const xmin=Math.min(...x),xmax=Math.max(...x),ymin=Math.min(...y),ymax=Math.max(...y);return {xmin:xmin-Math.max((xmax-xmin)*.08,.1),xmax:xmax+Math.max((xmax-xmin)*.08,.1),ymin:ymin-Math.max((ymax-ymin)*.08,.1),ymax:ymax+Math.max((ymax-ymin)*.08,.1)}});const X=(v:number)=>50+(v-bounds.value.xmin)/(bounds.value.xmax-bounds.value.xmin)*540;const Y=(v:number)=>228-(v-bounds.value.ymin)/(bounds.value.ymax-bounds.value.ymin)*195</script><template><div class="sample-cloud"><svg viewBox="0 0 630 280" role="img" aria-label="固定配方LHS模拟强度与成本散点"><g v-for="t in [0,.25,.5,.75,1]" :key="t"><line x1="50" x2="590" :y1="33+t*195" :y2="33+t*195" class="gridline"/><text x="1" :y="37+t*195">{{fixed(bounds.ymax-t*(bounds.ymax-bounds.ymin),0)}}</text><text :x="50+t*540" y="250" text-anchor="middle">{{fixed(bounds.xmin+t*(bounds.xmax-bounds.xmin),1)}}</text></g><line :x1="X(result.spec.strength_min)" :x2="X(result.spec.strength_min)" y1="25" y2="230" class="spec-line"/><circle v-for="r in result.robustness.samples" :key="r.index" :cx="X(r.strength)" :cy="Y(r.cost)" :r="2.4" :class="r.compliant?'pass-point':'fail-point'"/><text x="320" y="274" text-anchor="middle">模拟强度指数 / 纵轴元每吨</text></svg><div class="plot-caption"><span>● 全部质量界限内</span><span>● 至少一项超界</span><span>┆ 强度下界</span></div></div></template>
